    var miscarriages = form.get("ANC, Number of Miscarriages").getValue();
    form.getById(56).setValue(miscarriages);
  }
}"}},{"type":"obsControl","label":{"translationKey":"ANC,_LAST_NORMAL_MENSTRUAL_PERIOD_8","id":"8","units":"","type":"label","value":"Last Normal Menstrual Period"},"properties":{"mandatory":false,"notes":true,"addMore":false,"hideLabel":false,"controlEvent":true,"location":{"row":4,"column":0},"allowFutureDates":true},"id":"8","concept":{"name":"ANC, Last Normal Menstrual Period","uuid":"ca172e91-0b36-4b74-954c-2daad152c386","datatype":"Date","conceptClass":"Misc","conceptHandler":null,"units":null,"hiNormal":null,"lowNormal":null,"hiAbsolute":null,"lowAbsolute":null,"answers":[],"properties":{"allowDecimal":null}},"units":null,"hiNormal":null,"lowNormal":null,"hiAbsolute":null,"lowAbsolute":null,"events":{"onValueChange":"function(form) {
  var lnmp = form.get("ANC, Last Normal Menstrual Period").getValue();
  if (!lnmp || lnmp === "undefined") return;

  var d = new Date(lnmp);
  if (isNaN(d.getTime())) return;

  // --- Calculate EDD ---
  var edd = new Date(d.getFullYear() + 1, d.getMonth() - 3, d.getDate() + 7);

  var year = edd.getFullYear();
  var month = edd.getMonth() + 1;
  var day = edd.getDate();

  var pad = function(n) {
    return n < 10 ? "0" + n : n;
  };
  var eddString = year + "-" + pad(month) + "-" + pad(day);

  form.getById(57).setValue(lnmp);

  form.get("ANC, Estimated Date of Delivery").setValue(eddString);

  form.getById(58).setValue(eddString);

  // --- Determine "as of" date (retrospective or today) ---
  var asOfDate = new Date(); // default: today

  try {
    var match = document.cookie.match(
      /(?:^|;\s*)bahmni\.clinical\.retrospectiveEncounterDate=([^;]+)/
    );
    if (match && match[1]) {
      var decoded = decodeURIComponent(match[1]);
      var parsed = JSON.parse(decoded);
      var retroDate = new Date(parsed);
      if (!isNaN(retroDate.getTime())) {
        asOfDate = retroDate;
      }
    }
  } catch (e) {}

  // --- Calculate Gestational Age in completed weeks ---
  var msPerDay = 24 * 60 * 60 * 1000;
  var daysSinceLMP = Math.floor((asOfDate - d) / msPerDay);
  var weeks = Math.floor(daysSinceLMP / 7);

  if (weeks >= 0) {
