      uuid: "13382e01-9f18-488b-b2d2-58ab54c82d82",
      field: "HIVTC, ART Regimen",
      type: "coded"
    }
  ];

  // Function to fetch a single concept
  function fetchConcept(concept) {
    var params = new URLSearchParams({
      patient: patientUuid,
      concept: concept.uuid,
      v: "full",
      limit: "1"
    });

    var url = "/openmrs/ws/rest/v1/obs?" + params.toString();
    var xhr = new XMLHttpRequest();
    xhr.open("GET", url, false);
    xhr.send();

    if (xhr.status === 200) {
      var data = JSON.parse(xhr.responseText);

      if (data.results && data.results.length > 0) {
        var obs = data.results[0];
        var field = form.get(concept.field);

        if (field) {
          var value = null;

          // Handle different concept types
          if (concept.type === "coded") {
            // For coded concepts, try to extract from display string
            if (obs.display) {
              var displayParts = obs.display.split(": ");
              if (displayParts.length > 1) {
                value = displayParts[1];
              }
            }
          } else {
            // For numeric concepts
            value = obs.value;
          }

          // Only set if value is not null or undefined
          if (value !== null && value !== undefined && value !== "") {
            var strValue = String(value);
            // Check if ISO datetime using regex then normalize to YYYY-MM-DD for date fields if yes
            if (/^\d{4}-\d{2}-\d{2}T/.test(strValue)) {
              strValue = strValue.substring(0, 10);
            }
            field.setValue(strValue);
            console.log("Set", concept.field, "to", strValue);
          } else {
            console.log("No valid value found for", concept.field, "- leaving empty");
          }
        }
      } else {
        console.log("No data found for", concept.field);
      }
    } else {
      console.log("API call failed for", concept.field, "status:", xhr.status);
    }
  }

  // Fetch all concepts
  for (var i = 0; i < concepts.length; i++) {
    fetchConcept(concepts[i]);
  }

